1	/**
2	 * pysort.mjs — `sorted()` over Python strings.
3	 *
4	 * `str.__lt__` compares code points. JS's `<` compares UTF-16 code units, and
5	 * the two disagree for every astral character: U+1F600 encodes as D83D DE00, so
6	 * JS ranks it *below* U+E000..U+FFFF while Python ranks it above. The reference
7	 * executable confirms Python's order:
8	 *
9	 *   --a $'\xf0\x9f\x98\x80' --b $'\xef\xbf\xbd'
10	 *     -> b'["\xef\xbf\xbd","\xf0\x9f\x98\x80"]'   (U+FFFD sorts first)
11	 *
12	 * so the comparison below walks code points explicitly.
13	 */
14	
15	/** `(a > b) - (a < b)` for Python `str`, comparing code point by code point. */
16	export function compareCodePoints(a, b) {
17	  const ia = a[Symbol.iterator]();
18	  const ib = b[Symbol.iterator]();
19	
20	  for (;;) {
21	    const na = ia.next();
22	    const nb = ib.next();
23	    if (na.done) return nb.done ? 0 : -1; // a is a proper prefix of b
24	    if (nb.done) return 1;
25	    const ca = na.value.codePointAt(0);
26	    const cb = nb.value.codePointAt(0);
27	    if (ca !== cb) return ca < cb ? -1 : 1;
28	  }
29	}
30	
31	/**
32	 * `sorted(iterable)` for a sequence of strings.
33	 *
34	 * Returns a new array; the input is left untouched, matching `sorted()` rather
35	 * than `list.sort()`. `Array.prototype.sort` is stable in every supported V8,
36	 * which lines up with Python's Timsort for equal elements.
37	 */
38	export function pySorted(items) {
39	  return Array.from(items).sort(compareCodePoints);
40	}
41

1	/**
2	 * pyargv.mjs — recovers `sys.argv` with Python's byte-level fidelity.
3	 *
4	 * CPython decodes argv as UTF-8 with `errors='surrogateescape'`, so an argument
5	 * containing invalid UTF-8 survives as lone surrogates and later makes
6	 * `encode_canonical_json` raise `UnicodeEncodeError`. Node instead decodes argv
7	 * lossily: invalid bytes are already U+FFFD by the time `process.argv` exists,
8	 * which would silently succeed where Python fails.
9	 *
10	 *   /workspace/dataset/test7_executable --a $'bad\x80byte' --b x
11	 *     -> UnicodeEncodeError: ... '\udc80' in position 5 ...   (exit 1)
12	 *
13	 * Reading `/proc/self/cmdline` gets the original bytes back, so the
14	 * surrogateescape decode can be performed properly. The result is cross-checked
15	 * against `process.argv` and the whole mechanism falls back to `process.argv`
16	 * whenever the platform does not cooperate — for valid UTF-8 input, which is
17	 * every realistic invocation, both paths agree exactly.
18	 */
19	
20	import { readFileSync } from 'node:fs';
21	import { decodeSurrogateEscape } from './pyunicode.mjs';
22	
23	/** Split a NUL-delimited `/proc/self/cmdline` payload into byte slices. */
24	function splitCmdline(buffer) {
25	  let bytes = buffer;
26	  // The payload ends with a trailing NUL terminator; drop exactly one so that a
27	  // genuinely empty final argument is still preserved.
28	  if (bytes.length > 0 && bytes[bytes.length - 1] === 0) {
29	    bytes = bytes.subarray(0, bytes.length - 1);
30	  }
31	  if (bytes.length === 0) return [];
32	
33	  const parts = [];
34	  let start = 0;
35	  for (let i = 0; i < bytes.length; i += 1) {
36	    if (bytes[i] === 0) {
37	      parts.push(bytes.subarray(start, i));
38	      start = i + 1;
39	    }
40	  }
41	  parts.push(bytes.subarray(start));
42	  return parts;
43	}
44	
45	/**
