181	export class ArgumentParser {
182	  constructor(options = {}) {
183	    this.prog = options.prog !== undefined ? options.prog : process.env.ARGPARSE_PROG || DEFAULT_PROG;
184	    this.prefixChars = options.prefixChars || '-';
185	    this.allowAbbrev = options.allowAbbrev !== false;
186	    this.addHelp = options.addHelp !== false;
187	
188	    this.actions = [];
189	    this.optionStringActions = new Map();
190	    // Set when an option string itself looks like a negative number, which
191	    // flips how `-5`-style values are interpreted.
192	    this.hasNegativeNumberOptionals = false;
193	
194	    if (this.addHelp) {
195	      this.addArgument(['-h', '--help'], {
196	        action: 'help',
197	        nargs: 0,
198	        help: 'show this help message and exit',
199	      });
200	    }
201	  }
202	
203	  /**
204	   * Terminal width, mirroring `shutil.get_terminal_size().columns - 2`:
205	   * `COLUMNS` wins when it parses to a positive integer, otherwise the real
206	   * terminal size, otherwise the 80-column fallback (the case that applies
207	   * whenever output is redirected, i.e. under any test harness).
208	   */
209	  get formatterWidth() {
210	    const fromEnv = parseInt(process.env.COLUMNS || '', 10);
211	    if (Number.isFinite(fromEnv) && fromEnv > 0) return fromEnv - 2;
212	    const tty = process.stdout && process.stdout.isTTY ? process.stdout.columns : 0;
213	    return (tty > 0 ? tty : 80) - 2;
214	  }
215	
216	  /** `add_argument('--a', type=str, required=True)` */
217	  addArgument(optionStrings, options = {}) {
218	    const strings = Array.isArray(optionStrings) ? optionStrings : [optionStrings];
219	    const longest = strings.find((s) => s.startsWith(this.prefixChars.repeat(2))) || strings[0];
220	    const dest = options.dest || longest.replace(/^-+/, '').replace(/-/g, '_');
221	
222	    const action = {
223	      optionStrings: strings,
224	      dest,
225	      required: options.required === true,
226	      nargs: options.nargs !== undefined ? options.nargs : null,
227	      metavar: options.metavar !== undefined ? options.metavar : null,
228	      help: options.help !== undefined ? options.help : null,
229	      action: options.action || 'store',
230	      defaultValue: options.default !== undefined ? options.default : null,
231	    };
232	
233	    this.actions.push(action);
234	    for (const optionString of strings) {
235	      this.optionStringActions.set(optionString, action);
236	      if (NEGATIVE_NUMBER.test(optionString)) this.hasNegativeNumberOptionals = true;
237	    }
238	    return action;
239	  }
240	
241	  formatUsage() {
242	    return new HelpFormatter(this.prog, this.formatterWidth).formatUsage(this.actions);
243	  }
244	
245	  formatHelp() {
246	    const formatter = new HelpFormatter(this.prog, this.formatterWidth);
247	    return `${formatter.formatUsage(this.actions)}\n${formatter.formatOptionsSection(this.actions)}`;
248	  }
249	
250	  printHelp() {
251	    writeStdout(this.formatHelp());
252	  }
253	
254	  /** `parser.error(message)` — usage on stderr, then `sys.exit(2)`. */
255	  error(message) {
256	    writeStderr(this.formatUsage());
257	    writeStderr(`${this.prog}: error: ${message}\n`);
258	    throw new SystemExit(2);
259	  }
260	
261	  /**
262	   * `_parse_optional`. Returns `null` when the string is a positional, or
263	   * `[action, optionString, sep, explicitArg]` where `action` is `null` for an
264	   * option-looking string that matches nothing.
265	   *
266	   * `sep` records *how* an explicit argument was attached: `'='` when it was
267	   * split off an `=`, `''` when it was concatenated onto a single-dash option
268	   * (`-hx`), and `null` when there is none. The distinction is load-bearing —
269	   * `-hx` chains into another short option while `-h=x` is an error.
270	   */
271	  parseOptional(argString) {
272	    if (argString === '') return null;
273	    if (!this.prefixChars.includes(argString[0])) return null;
274	
275	    if (this.optionStringActions.has(argString)) {
276	      return [this.optionStringActions.get(argString), argString, null, null];
277	    }
278	    if (argString.length === 1) return null; // a bare "-" is a positional
279	
280	    const equalsAt = argString.indexOf('=');
281	    if (equalsAt !== -1) {
282	      const optionString = argString.slice(0, equalsAt);
283	      const explicitArg = argString.slice(equalsAt + 1);
284	      if (this.optionStringActions.has(optionString)) {
285	        return [this.optionStringActions.get(optionString), optionString, '=', explicitArg];
286	      }
287	    }
288	
289	    const tuples = this.getOptionTuples(argString);
290	    if (tuples.length > 1) {
291	      const matches = tuples.map(([, optionString]) => optionString).join(', ');
292	      this.error(`ambiguous option: ${argString} could match ${matches}`);
293	    } else if (tuples.length === 1) {
294	      return tuples[0];
295	    }
296	
297	    if (NEGATIVE_NUMBER.test(argString) && !this.hasNegativeNumberOptionals) return null;
298	    if (argString.includes(' ')) return null;
299	
300	    return [null, argString, null, null];
301	  }
302	
303	  /** `_get_option_tuples` — prefix matching for long and short options. */
304	  getOptionTuples(optionString) {
305	    const chars = this.prefixChars;
306	    const result = [];
307	
308	    // A double-dash option is only ever split at an '='.
309	    if (chars.includes(optionString[0]) && chars.includes(optionString[1])) {
310	      if (!this.allowAbbrev) return result;
311	      const equalsAt = optionString.indexOf('=');
312	      const prefix = equalsAt !== -1 ? optionString.slice(0, equalsAt) : optionString;
313	      const sep = equalsAt !== -1 ? '=' : null;
314	      const explicitArg = equalsAt !== -1 ? optionString.slice(equalsAt + 1) : null;
315	      for (const [candidate, action] of this.optionStringActions) {
316	        if (candidate.startsWith(prefix)) result.push([action, candidate, sep, explicitArg]);
317	      }
318	      return result;
319	    }
320	
321	    // A single-dash option may have its argument concatenated onto it.
322	    const shortPrefix = optionString.slice(0, 2);
323	    const shortExplicitArg = optionString.slice(2);
324	    for (const [candidate, action] of this.optionStringActions) {
325	      if (candidate === shortPrefix) {
326	        result.push([action, candidate, '', shortExplicitArg]);
327	      } else if (candidate.startsWith(optionString)) {
328	        result.push([action, candidate, null, null]);
329	      }
330	    }
331	    return result;
332	  }
333	
334	  /**
335	   * `_match_argument` for `nargs=None`. For optionals argparse strips `-` from
336	   * the nargs pattern, leaving `(A)`: the very next slot must be a plain value,
337	   * so a following option string or `--` is a hard error.
338	   */
339	  matchArgument(action, pattern) {
340	    if (action.nargs === 0) return 0;
341	    if (pattern.length >= 1 && pattern[0] === 'A') return 1;
342	    throw new ArgumentError(action, 'expected one argument');
343	  }
344	
345	  /** `parse_args` */
346	  parseArgs(args) {
347	    const [namespace, extras] = this.parseKnownArgs(args);
348	    if (extras.length > 0) {
349	      this.error(`unrecognized arguments: ${extras.join(' ')}`);
350	    }
351	    return namespace;
352	  }
353	
354	  /** `parse_known_args` / `_parse_known_args` */
355	  parseKnownArgs(argStrings) {
356	    const args = Array.from(argStrings);
357	    const namespace = new Namespace();
358	    for (const action of this.actions) {
359	      if (action.action === 'store') namespace[action.dest] = action.defaultValue;
360	    }
361	
362	    // Classify each argument: 'O' option, 'A' value, '-' the "--" separator.
363	    const pattern = [];
364	    const optionIndices = new Map();
365	    let sawSeparator = false;
366	    for (let i = 0; i < args.length; i += 1) {
367	      if (sawSeparator) {
368	        pattern.push('A');
369	        continue;
370	      }
371	      if (args[i] === '--') {
372	        pattern.push('-');
373	        sawSeparator = true;
374	        continue;
375	      }
376	      const optionTuple = this.parseOptional(args[i]);
377	      if (optionTuple === null) {
378	        pattern.push('A');
379	      } else {
380	        optionIndices.set(i, optionTuple);
381	        pattern.push('O');
382	      }
383	    }
384	
385	    const seenActions = new Set();
386	    const extras = [];
387	
388	    const takeAction = (action, values) => {
389	      seenActions.add(action);
390	      if (action.action === 'help') {
391	        this.printHelp();
392	        throw new SystemExit(0);
393	      }
394	      // type=str is the identity conversion.
395	      namespace[action.dest] = action.nargs === 0 ? true : values[0];
396	    };
397	
398	    /**
399	     * `consume_optional`. Actions are collected into `actionTuples` and only
400	     * applied once the loop settles, so an error raised part-way through a
401	     * concatenated short-option chain applies nothing at all.
402	     */
403	    const consumeOptional = (startIndex) => {
404	      let [action, optionString, sep, explicitArg] = optionIndices.get(startIndex);
405	      const actionTuples = [];
406	      let stop;
407	
408	      for (;;) {
409	        if (action === null) {
410	          extras.push(args[startIndex]);
411	          return startIndex + 1;
412	        }
413	
414	        if (explicitArg !== null) {
415	          const argCount = this.matchArgument(action, ['A']);
416	          const chars = this.prefixChars;
417	
418	          if (argCount === 0 && !chars.includes(optionString[1]) && explicitArg !== '') {
419	            // A single-dash flag with something glued to it: try to read the
420	            // tail as further short options, as in `-hx` -> `-h` then `-x`.
421	            // An explicit `=` or a dash-prefixed tail is a hard error instead.
422	            if (sep || chars.includes(explicitArg[0])) {
423	              throw new ArgumentError(action, `ignored explicit argument '${explicitArg}'`);
424	            }
425	            actionTuples.push([action, [], optionString]);
426	            const char = optionString[0];
427	            optionString = char + explicitArg[0];
428	            if (this.optionStringActions.has(optionString)) {
429	              action = this.optionStringActions.get(optionString);
430	              explicitArg = explicitArg.slice(1);
431	              if (explicitArg === '') {
432	                sep = null;
433	                explicitArg = null;
434	              } else if (explicitArg[0] === '=') {
435	                sep = '=';
436	                explicitArg = explicitArg.slice(1);
437	              } else {
438	                sep = '';
439	              }
440	              continue;
441	            }
442	            extras.push(char + explicitArg);
443	            stop = startIndex + 1;
444	            break;
445	          }
446	
447	          if (argCount === 1) {
448	            stop = startIndex + 1;
449	            actionTuples.push([action, [explicitArg], optionString]);
450	            break;
451	          }
452	
453	          throw new ArgumentError(action, `ignored explicit argument '${explicitArg}'`);
454	        }
455	
456	        const start = startIndex + 1;
457	        const argCount = this.matchArgument(action, pattern.slice(start));
458	        stop = start + argCount;
459	        actionTuples.push([action, args.slice(start, stop)]);
460	        break;
461	      }
462	
463	      for (const [tupleAction, values] of actionTuples) takeAction(tupleAction, values);
464	      return stop;
465	    };
466	
467	    const optionKeys = Array.from(optionIndices.keys());
468	    const maxOptionIndex = optionKeys.length > 0 ? Math.max(...optionKeys) : -1;
469	
470	    let startIndex = 0;
471	    try {
472	      while (startIndex <= maxOptionIndex) {
473	        const nextOptionIndex = Math.min(...optionKeys.filter((index) => index >= startIndex));
474	        // No positionals are declared, so anything before the next option is
475	        // unparseable and goes straight to extras.
476	        if (startIndex !== nextOptionIndex) {
477	          extras.push(...args.slice(startIndex, nextOptionIndex));
478	          startIndex = nextOptionIndex;
479	        }
480	        startIndex = consumeOptional(nextOptionIndex);
481	      }
482	    } catch (err) {
483	      if (err instanceof ArgumentError) this.error(err.message);
484	      throw err;
485	    }
486	
487	    extras.push(...args.slice(startIndex));
488	
489	    const missing = this.actions
490	      .filter((action) => action.required && !seenActions.has(action))
491	      .map((action) => action.optionStrings.join('/'));
492	    if (missing.length > 0) {
493	      this.error(`the following arguments are required: ${missing.join(', ')}`);
494	    }
495	
496	    return [namespace, extras];
497	  }
498	}
