/**
 * random-differential.mjs — high-volume pure-random differential fuzzing of
 * /output/test7.mjs against /workspace/dataset/test7_executable.
 *
 * Deterministic: every byte comes from a xorshift32 PRNG seeded with a constant,
 * so `--seed S --count N` always produces the identical case list and any
 * failure is reproducible. Each case is labelled with the exact bash command
 * that reproduces it.
 *
 * Usage:
 *   node /tmp/dh/random-differential.mjs [--seed S] [--count N] [--shards K]
 *   node /tmp/dh/random-differential.mjs --shard I --shards K ...   (internal)
 */
import { runSuite } from '/tmp/dh/harness.mjs';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const SELF = fileURLToPath(import.meta.url);

/* ------------------------------------------------------------------ PRNG --- */

/** xorshift32 — fixed seed in, deterministic uint32 stream out. */
function makeRng(seed) {
  let s = seed >>> 0;
  if (s === 0) s = 0x9e3779b9;
  return function next() {
    s ^= s << 13;
    s >>>= 0;
    s ^= s >>> 17;
    s ^= s << 5;
    s >>>= 0;
    return s;
  };
}

/* ------------------------------------------------------- byte generators --- */

const JSON_META = Buffer.from('"\\/{}[]:,\'`<>&%$#@!?*+-=~^|;()');
const CONTROLS = [];
for (let b = 1; b <= 0x1f; b += 1) CONTROLS.push(b);
CONTROLS.push(0x7f);

const OVERLONG = [
  [0xc0, 0x80],
  [0xc1, 0xbf],
  [0xe0, 0x80, 0x80],
  [0xe0, 0x9f, 0xbf],
  [0xf0, 0x80, 0x80, 0x80],
  [0xf0, 0x8f, 0xbf, 0xbf],
];

const OUT_OF_RANGE = [
  [0xf4, 0x90, 0x80, 0x80],
  [0xf5, 0x80, 0x80, 0x80],
  [0xf8, 0x88, 0x80, 0x80, 0x80],
  [0xfc, 0x84, 0x80, 0x80, 0x80, 0x80],
  [0xfe],
  [0xff],
  [0xff, 0xfe],
];

const LITERAL_SNIPPETS = [
  '\\u0000',
  '\\n',
  '\\"',
  '\\\\',
  '\\udc80',
  '\\ud800',
  'b\'',
  '"]',
  '["',
  '\',"',
  '--a',
  '--b',
  '-h',
  '=',
  '--',
];

function utf8OfCodePoint(cp) {
  if (cp < 0x80) return [cp];
  if (cp < 0x800) return [0xc0 | (cp >> 6), 0x80 | (cp & 0x3f)];
  if (cp < 0x10000) return [0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f)];
  return [
    0xf0 | (cp >> 18),
    0x80 | ((cp >> 12) & 0x3f),
    0x80 | ((cp >> 6) & 0x3f),
    0x80 | (cp & 0x3f),
  ];
}

/**
 * Builds one blob of `target` bytes (approximately — a fragment may overshoot
 * slightly, which is deliberate) from a mixed alphabet.
 */
function makeBlob(rng, target) {
  const pick = (n) => rng() % n;
  const out = [];

  while (out.length < target) {
    switch (pick(14)) {
      case 0: // ASCII printable
      case 1:
        out.push(0x20 + pick(0x5f));
        break;
      case 2: // ASCII control (never NUL — unrepresentable in argv)
        out.push(CONTROLS[pick(CONTROLS.length)]);
        break;
      case 3: // JSON metacharacter / quote / backslash
      case 4:
        out.push(JSON_META[pick(JSON_META.length)]);
        break;
      case 5: { // random valid code point, uniform over all 17 planes
        let cp;
        do {
          cp = pick(17) * 0x10000 + pick(0x10000);
        } while (cp >= 0xd800 && cp <= 0xdfff);
        out.push(...utf8OfCodePoint(cp));
        break;
      }
      case 6: { // random valid code point, biased to BMP
        let cp;
        do {
          cp = pick(0x10000);
        } while (cp >= 0xd800 && cp <= 0xdfff);
        out.push(...utf8OfCodePoint(cp));
        break;
      }
      case 7: // raw random byte (any value but NUL)
        out.push(1 + pick(0xff));
        break;
      case 8: // raw high byte — almost always invalid UTF-8 on its own
        out.push(0x80 + pick(0x80));
        break;
      case 9: { // truncated UTF-8 sequence
        let cp;
        do {
          cp = 0x80 + pick(0x10ff80);
        } while (cp >= 0xd800 && cp <= 0xdfff);
        const seq = utf8OfCodePoint(cp);
        out.push(...seq.slice(0, 1 + pick(seq.length - 1)));
        break;
      }
      case 10: // overlong encoding
        out.push(...OVERLONG[pick(OVERLONG.length)]);
        break;
      case 11: // UTF-8-encoded surrogate (CESU-style)
        out.push(0xed, 0xa0 + pick(0x20), 0x80 + pick(0x40));
        break;
      case 12: // out-of-range / illegal lead byte
        out.push(...OUT_OF_RANGE[pick(OUT_OF_RANGE.length)]);
        break;
      default: // literal ASCII snippet with JSON/py-repr significance
        out.push(...Buffer.from(LITERAL_SNIPPETS[pick(LITERAL_SNIPPETS.length)], 'utf8'));
        break;
    }
  }

  return Buffer.from(out.slice(0, Math.max(target, 0) === 0 ? 0 : out.length));
}

/** Length distribution: mostly short, sometimes up to the full 200 bytes. */
function randomLength(rng) {
  const r = rng() % 100;
  if (r < 12) return 0;
  if (r < 45) return rng() % 9; // 0..8, the interesting edge sizes
  if (r < 80) return rng() % 33; // 0..32
  return rng() % 201; // 0..200
}

function randomBlob(rng) {
  return makeBlob(rng, randomLength(rng));
}

/** Occasionally force an option-looking value to stress _parse_optional. */
function maybeOptionLike(rng, blob) {
  const r = rng() % 100;
  if (r < 6) return Buffer.concat([Buffer.from('-'), blob]);
  if (r < 10) return Buffer.concat([Buffer.from('--'), blob]);
  if (r < 13) {
    const NEG = ['-5', '-.5', '-1.5e3', '-1.', '-0', '-12345', '- x', '-', '--'];
    return Buffer.from(NEG[rng() % NEG.length]);
  }
  return blob;
}

/* ------------------------------------------------------------ case shapes --- */

const NOISE_TOKENS = [
  '--a', '--b', '-h', '--help', '--', '-', '--h', '--he', '--ab', '-a', '-b',
  '-x', '--a=', '--b=', '=', '--=', '-hx', '-h=x', '--A', '--B', '--a=1',
];

function makeCase(rng, index) {
  const pick = (n) => rng() % n;
  const a = maybeOptionLike(rng, randomBlob(rng));
  const b = maybeOptionLike(rng, randomBlob(rng));
  const cat = (p, v) => Buffer.concat([Buffer.from(p), v]);

  let argv;
  switch (pick(12)) {
    case 0:
    case 1:
    case 2:
    case 3:
      argv = ['--a', a, '--b', b];
      break;
    case 4:
      argv = ['--b', b, '--a', a];
      break;
    case 5:
      argv = [cat('--a=', a), cat('--b=', b)];
      break;
    case 6:
      argv = [cat('--a=', a), '--b', b];
      break;
    case 7:
      argv = ['--a', a, cat('--b=', b)];
      break;
    case 8:
      argv = ['--a', a, '--b', b, Buffer.from(NOISE_TOKENS[pick(NOISE_TOKENS.length)])];
      break;
    case 9: {
      // abbreviated / mis-cased option names around real values
      const opts = ['--a', '--b', '--a=', '--b=', '--h', '--hel', '-h'];
      argv = [Buffer.from(opts[pick(opts.length)]), a, Buffer.from(opts[pick(opts.length)]), b];
      break;
    }
    case 10: {
      // fully random argv drawn from noise tokens and random blobs
      const n = pick(6);
      argv = [];
      for (let i = 0; i < n; i += 1) {
        argv.push(pick(3) === 0 ? randomBlob(rng) : Buffer.from(NOISE_TOKENS[pick(NOISE_TOKENS.length)]));
      }
      break;
    }
    default:
      // same value twice (equal-element sort stability) or a prefix pair
      argv = pick(2) === 0
        ? ['--a', a, '--b', Buffer.from(a)]
        : ['--a', a, '--b', Buffer.concat([a, randomBlob(rng)])];
      break;
  }

  const env = {};
  if (pick(40) === 0) env.COLUMNS = String([0, 1, 20, 40, 60, 80, 120, 200][pick(8)]);

  return { argv, env, label: `#${index} ${repro(argv, env)}` };
}

/** The exact bash command the harness runs — copy/paste reproducible. */
function bashQuote(buf) {
  let out = "$'";
  for (const byte of buf) out += '\\x' + byte.toString(16).padStart(2, '0');
  return out + "'";
}

function repro(argv, env) {
  const envPart = Object.entries(env)
    .map(([k, v]) => `${k}=${bashQuote(Buffer.from(v))}`)
    .join(' ');
  const args = argv
    .map((v) => bashQuote(Buffer.isBuffer(v) ? v : Buffer.from(String(v), 'utf8')))
    .join(' ');
  return `${envPart ? envPart + ' ' : ''}node /output/test7.mjs ${args}`;
}

/* ------------------------------------------------------------------- main --- */

function argOf(name, fallback) {
  const i = process.argv.indexOf(name);
  return i === -1 ? fallback : process.argv[i + 1];
}

const SEED = Number(argOf('--seed', '0x5eed1234'.replace('0x', '')) ) || 0x5eed1234;
const COUNT = Number(argOf('--count', '6000'));
const SHARDS = Number(argOf('--shards', '20'));
const SHARD = argOf('--shard', null);

function buildCases() {
  const rng = makeRng(SEED);
  const cases = [];
  for (let i = 0; i < COUNT; i += 1) cases.push(makeCase(rng, i));
  return cases;
}

if (SHARD !== null) {
  const shard = Number(SHARD);
  const mine = buildCases().filter((_, i) => i % SHARDS === shard);
  const failed = runSuite(`shard${shard}`, mine);
  process.stdout.write(`SHARD_RESULT ${shard} ${failed} ${mine.length}\n`);
  process.exit(0);
}

// Parent: fan the deterministic case list out across `SHARDS` child processes.
console.log(`seed=0x${SEED.toString(16)} count=${COUNT} shards=${SHARDS}`);
const started = Date.now();
let totalFailed = 0;
let totalRan = 0;

await Promise.all(
  Array.from({ length: SHARDS }, (_, shard) =>
    new Promise((resolve) => {
      const child = spawn(
        process.execPath,
        [SELF, '--shard', String(shard), '--shards', String(SHARDS), '--seed', String(SEED), '--count', String(COUNT)],
        { stdio: ['ignore', 'pipe', 'inherit'] },
      );
      let buf = '';
      child.stdout.on('data', (chunk) => {
        buf += chunk;
      });
      child.on('close', () => {
        for (const line of buf.split('\n')) {
          if (line.startsWith('SHARD_RESULT')) {
            const [, , f, n] = line.split(' ');
            totalFailed += Number(f);
            totalRan += Number(n);
          } else if (/^\[shard\d+\]/.test(line)) {
            // per-shard tally, folded into the total below
          } else if (line.length > 0) {
            process.stdout.write(line + '\n');
          }
        }
        resolve();
      });
    }),
  ),
);

console.log(
  `TOTAL ${totalRan - totalFailed}/${totalRan} passed, ${totalFailed} failed ` +
    `in ${((Date.now() - started) / 1000).toFixed(1)}s`,
);
process.exit(totalFailed ? 1 : 0);

