input.content:
import { readFileSync, writeFileSync } from 'node:fs';

const file = process.argv[2];
const lines = readFileSync(file, 'utf8').split('\n');
const blocks = [];
let cur = null;
for (const l of lines) {
  if (l.startsWith('FAIL ')) {
    if (cur) blocks.push(cur);
    cur = { head: l, body: [] };
  } else if (cur && (l.startsWith('  ') || l === '')) {
    cur.body.push(l);
  } else if (cur) {
    blocks.push(cur);
    cur = null;
  }
}
if (cur) blocks.push(cur);
console.log('blocks', blocks.length);

const sig = new Map();
for (const b of blocks) {
  const kinds = b.body.filter((x) => /^ {2}\S/.test(x)).map((x) => x.trim());
  const k = kinds.join(' + ');
  if (!sig.has(k)) sig.set(k, []);
  sig.get(k).push(b);
}
for (const [k, v] of [...sig].sort((a, b) => b[1].length - a[1].length)) {
  console.log('===', v.length, '|', k);
  console.log('   e.g.', v[0].head.slice(0, 300));
  for (const line of v[0].body.slice(0, 8)) console.log('   ', line.slice(0, 300));
}
writeFileSync(file.replace('.txt', '.json'), JSON.stringify(blocks, null, 1));

import { runSuite } from '/tmp/dh/harness.mjs';

const cases = [];
for (let c = 1; c <= 120; c += 1) {
  const env = { COLUMNS: String(c) };
  cases.push({ argv: ['--help'], env, label: `COLUMNS=${c} --help` });
  cases.push({ argv: [], env, label: `COLUMNS=${c} (missing required)` });
  cases.push({ argv: ['--a', '1', '--b', '2', 'zz'], env, label: `COLUMNS=${c} unrecognized` });
  cases.push({ argv: ['--a'], env, label: `COLUMNS=${c} expected-one-arg` });
}
process.exit(runSuite('columns-sweep', cases) ? 1 : 0);
